const REGIONS = [["kanto","Kanto",1,151],["johto","Johto",152,251],["hoenn","Hoenn",252,386],["sinnoh","Sinnoh",387,493],["unova","Unova",494,649],["kalos","Kalos",650,721],["alola","Alola",722,807],["other","Outros",808,809],["galar","Galar",810,898],["hisui","Hisui",899,905],["paldea","Paldea",906,1025]];
REGIONS.forEach(([id,name,first,last]) => {
 const tabId='region-'+id;
 TABS[tabId]={id:tabId,list:REGIONAL_DEX.filter(p=>p.dex>=first&&p.dex<=last),storageKey:'pokemonRegion_'+id+'_v1',regional:true,
 pageTitle:name+' · Shinies e Shundos',pageSubtitle:'1 clique: shiny · 2 cliques: shundo (shiny + IV 100%). Clique novamente para desmarcar. No teclado: Enter para shiny, Shift + Enter para shundo.',
 exportTitle:name+' · Coleção regional',exportSubtitle:'Uma espécie por número da Pokédex · Formas alternativas empilhadas',exportFilePrefix:'pokemon-'+id,unitLabel:'shinies',searchPlaceholder:'Buscar Pokémon, número ou tipo...',hasWaitingState:true,useShinyImages:true,categoryLabels:{base:'Forma principal'},statusLabels:{all:'Todos',caught:'Shinies coletados (inclui shundos)',missing:'Shinies que faltam',waiting:'Shundos coletados',missingShundo:'Shundos que faltam',owned:'Somente shiny (sem shundo)'},statusOrder:['all','caught','missing','waiting','missingShundo','owned'],emptyMessage:'Nenhum Pokémon corresponde aos filtros.',allLabel:'Todos os Pokémon',footerNote:'Pokédex nacional completa, incluindo espécies ainda não lançadas. ⚠ indica shiny não liberado para a forma principal. Dados Dittobase consultados em 09/10/2026; disponibilidade não atualiza automaticamente.',footerSource:'https://www.dittobase.com/pokemon-go/pokedex'};
});

let currentTabId = "mega";

const state = {};

Object.keys(TABS).forEach(tabId => {

    const cfg = TABS[tabId];

    let stored = {};

    try {
        stored = JSON.parse(localStorage.getItem(cfg.storageKey)) || {};
    } catch (e) {
        stored = {};
    }

    /*
     * Normaliza para o formato de marcação em texto.
     * Backups antigos guardavam "true", que equivale a "owned".
     */
    const marks = {};

    Object.keys(stored).forEach(slug => {

        const value = stored[slug];

        if (value === true || value === MARK_OWNED) {
            marks[slug] = MARK_OWNED;
        } else if (value === MARK_WAITING) {
            marks[slug] = MARK_WAITING;
        }

    });

    state[tabId] = {
        marks: marks,
        search: "",
        statusFilter: "all",
        selectedCategories: new Set(),
        selectedRegions: new Set(),
        selectedTypes: new Set()
    };

});

