if(archivedTabs.has(currentTabId)){const available=Object.keys(TABS).find(id=>!archivedTabs.has(id));if(available)currentTabId=available;}

const expandedEvolutionDecks=new Set();
const baseMarkOf=markOf;
markOf=function(p,tabId){
 const target=tabId||currentTabId;
 if(!TABS[target].regional||p.isForm||!p.forms)return baseMarkOf(p,target);
 const marks=p.forms.map(f=>baseMarkOf(f,target));
 return marks.includes(MARK_WAITING)?MARK_WAITING:marks.includes(MARK_OWNED)?MARK_OWNED:MARK_NONE;
};
function attachEvolutionDeck(primary,species){
 const tabId=currentTabId,key=tabId+':'+species.dex;
 const deck=document.createElement('div');deck.className='evolution-deck';deck.dataset.dex=species.dex;
 const expanded=expandedEvolutionDecks.has(key);deck.classList.toggle('expanded',expanded);
 function toggle(){if(currentTabId!==tabId)return;if(expandedEvolutionDecks.has(key))expandedEvolutionDecks.delete(key);else expandedEvolutionDecks.add(key);render();}
 function attachHold(card){
  let holdTimer=null,suppressClick=false,start=null;
  const cancel=()=>{clearTimeout(holdTimer);holdTimer=null;};
  card.addEventListener('pointerdown',e=>{if(e.button!==0||e.isPrimary===false||e.target.closest?.('.deck-toggle'))return;cancel();suppressClick=false;start={x:e.clientX,y:e.clientY};holdTimer=setTimeout(()=>{if(!card.isConnected||currentTabId!==tabId)return;suppressClick=true;toggle();},550);});
  card.addEventListener('pointermove',e=>{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>10)cancel();});
  ['pointerup','pointercancel','pointerleave'].forEach(type=>card.addEventListener(type,cancel));
  ['click','dblclick'].forEach(type=>card.addEventListener(type,e=>{if(suppressClick){e.preventDefault();e.stopImmediatePropagation();}},true));
  card.addEventListener('contextmenu',e=>{cancel();e.preventDefault();});
  card.addEventListener('keydown',e=>{if(e.key==='F2'){e.preventDefault();toggle();}});
 }
 if(expanded){const caption=document.createElement('p');caption.className='deck-caption';caption.textContent=species.forms.length+' formas · Um único número da Pokédex · Segure uma carta para recolher';deck.append(caption);}
 const button=document.createElement('button');button.type='button';button.className='deck-toggle';button.textContent=expanded?'▤ Recolher formas':'▤ '+species.forms.length+' formas · segure';button.setAttribute('aria-expanded',String(expanded));button.setAttribute('aria-label',(expanded?'Recolher':'Mostrar')+' formas de '+species.name);button.onclick=e=>{e.stopPropagation();toggle();};button.addEventListener('dblclick',e=>e.stopPropagation());button.addEventListener('keydown',e=>e.stopPropagation());primary.append(button);attachHold(primary);deck.append(primary);
 if(expanded)species.forms.filter(form=>form.slug!==(primary.dataset.formSlug||species.slug)&&matchesAvailabilityForm(form)).forEach(form=>{
  const p={...form,isForm:true};const card=document.createElement('div');card.className='card';card.setAttribute('role','button');card.setAttribute('tabindex','0');
  card.innerHTML='<div class="dex">#'+String(p.dex).padStart(3,'0')+'</div><div class="check"><svg class="icon-check" viewBox="0 0 24 24" fill="none" stroke="#0e0a1a" stroke-width="3"><polyline points="20 6 9 17 4 12"/></svg><svg class="icon-wait" viewBox="0 0 24 24" fill="none" stroke="#0e0a1a" stroke-width="2.6"></svg></div><img loading="lazy" alt="'+escapeXml(p.name)+'"><div class="name">'+escapeXml(p.name)+'</div><div class="type-row">'+p.types.map(t=>'<span class="type-badge" style="color:'+TYPE_COLORS[t]+';border-color:'+TYPE_COLORS[t]+'55;background:'+TYPE_COLORS[t]+'22">'+TYPE_LABELS[t]+'</span>').join('')+'</div><div class="category-badge">Forma alternativa</div>';
  attachImageFallback(card.querySelector('img'),p);refreshCardMark(card,p);
  let firstMark=MARK_NONE,filterTimer;
  function apply(mark){if(currentTabId!==tabId)return;setMark(p,mark);refreshCardMark(card,p);updateProgress();clearTimeout(filterTimer);if(st().statusFilter!=='all')filterTimer=setTimeout(()=>{if(currentTabId===tabId&&card.isConnected)render();},600);}
  card.addEventListener('click',e=>{if(e.detail===3){clearTimeout(filterTimer);if(currentTabId!==tabId)return;setMark(p,firstMark);refreshCardMark(card,p);updateProgress();openTradeEditor(p);return;}if(e.detail>1)return;firstMark=markOf(p);apply(firstMark===MARK_OWNED?MARK_NONE:MARK_OWNED);});
  card.addEventListener('dblclick',()=>apply(firstMark===MARK_WAITING?MARK_NONE:MARK_WAITING));
  card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();const desired=e.shiftKey?MARK_WAITING:MARK_OWNED;apply(markOf(p)===desired?MARK_NONE:desired);}});
  attachHold(card);deck.append(card);
 });
 grid.append(deck);
}

// One content selector for TXT, PNG and SVG. Reading export filters never changes the page state.
const EXPORT_MODE_LABELS={view:'Visualização atual',shinyCollected:'Shinies coletados (inclui shundos)',shinyMissing:'Shinies que faltam',shundoCollected:'Shundos coletados',shundoMissing:'Shundos que faltam',collected:'Pokémon coletados',missing:'Pokémon que faltam'};
function exportMarkIcon(mark,size=13){
 if(mark===MARK_NONE)return '';
 const shundo=mark===MARK_WAITING&&config().regional;
 const status=mark===MARK_OWNED?'owned':shundo?'shundo':'waiting';
 const path=mark===MARK_OWNED?'<polyline points="20 6 9 17 4 12"/>':shundo?'<path d="m12 3 2.8 5.7 6.3.9-4.6 4.5 1.1 6.3-5.6-3-5.6 3 1.1-6.3L3 9.6l6.2-.9Z"/>':'<circle cx="12" cy="12" r="9"/><polyline points="12 7 12 12 16 14"/>';
 return '<svg data-export-status="'+status+'" width="'+size+'" height="'+size+'" viewBox="0 0 24 24" fill="none" stroke="'+(mark===MARK_OWNED?'#4fe0c4':'#ffc65c')+'" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round">'+path+'</svg>';
}
function selectedExportMode(){return document.getElementById('textListMode').value||'view';}
function collectionExportItems(mode){
 const s=st();if(mode==='view')return list().filter(matchesFilters);
 const saved=s.statusFilter;let items;
 try{s.statusFilter='all';items=list().filter(matchesFilters);}finally{s.statusFilter=saved;}
 return items.filter(p=>{const mark=markOf(p);switch(mode){
  case 'shinyCollected':case 'collected':return mark!==MARK_NONE;
  case 'shinyMissing':case 'missing':return mark===MARK_NONE;
  case 'shundoCollected':return mark===MARK_WAITING;
  case 'shundoMissing':return mark!==MARK_WAITING;
  default:return false;
 }});
}
makeExportItems=function(){return collectionExportItems(selectedExportMode());};
const pageExportFilterText=exportFilterText;
exportFilterText=function(){const mode=selectedExportMode();if(mode==='view')return pageExportFilterText();
 const s=st(),saved=s.statusFilter;let labels;
 try{s.statusFilter='all';labels=activeFilterLabels();}finally{s.statusFilter=saved;}
 if(s.search)labels.push('Busca: '+s.search);
 return [EXPORT_MODE_LABELS[mode],...labels].join(' · ');
};

