const COMBINED_REGION_ID='combined-regions';
const regionChoices=new Set();let choosingRegions=false,combinedConfig=null;
const regionOwner=new Map();Object.entries(TABS).filter(([,c])=>c.regional).forEach(([id,c])=>c.list.forEach(p=>regionOwner.set(p.dex,id)));
const originalRegionConfig=config,originalRegionState=st,originalRegionMark=markOf,originalRegionSetMark=setMark;
const combinedState={marks:{},search:'',statusFilter:'all',selectedCategories:new Set(),selectedRegions:new Set(),selectedTypes:new Set()};
