setMark=function(p,mark){if(currentTabId!==COMBINED_REGION_ID)return originalRegionSetMark(p,mark);const id=regionOwner.get(p.dex);if(!id)return;if(mark===MARK_NONE)delete state[id].marks[p.slug];else state[id].marks[p.slug]=mark;try{localStorage.setItem(TABS[id].storageKey,JSON.stringify(state[id].marks));}catch{showToast('Não foi possível salvar o progresso neste navegador.');}};
