const availability={hideUnreleased:false,hideUnreleasedShiny:false};
try{const saved=JSON.parse(localStorage.getItem('pokemonAvailabilityFilters_v1'));availability.hideUnreleased=saved?.hideUnreleased===true;availability.hideUnreleasedShiny=saved?.hideUnreleasedShiny===true;}catch{}
function availabilityLabels(){return [availability.hideUnreleased?'Ocultar Pokémon não lançados':null,availability.hideUnreleasedShiny?'Ocultar shinies não liberados':null].filter(Boolean);}
