const availabilityStyle=document.createElement('style');availabilityStyle.textContent='.availability-controls{display:flex;flex-wrap:wrap;gap:12px;margin:0 0 16px}.availability-category{margin:0;padding:10px 12px 12px;border:1px solid var(--border);border-radius:12px;background:var(--surface-2);min-width:200px}.availability-category legend{padding:0 6px;color:var(--text-muted);font-size:12px}.availability-choices{display:flex;gap:7px}.availability-choices .filter-chip{flex:1;justify-content:center}.is-home .availability-controls{display:none!important}@media(max-width:520px){.availability-category{flex:1;min-width:0}}';document.querySelector('head').append(availabilityStyle);
function availabilityProgressStats(){const species=list().map(p=>({p,forms:(p.forms||[p]).filter(matchesAvailabilityForm)})).filter(entry=>entry.forms.length);let shiny=0,shundo=0;for(const entry of species){const marks=entry.forms.map(form=>markOf({...form,isForm:true}));if(marks.some(mark=>mark===MARK_OWNED||mark===MARK_WAITING))shiny++;if(marks.includes(MARK_WAITING))shundo++;}return {total:species.length,shiny,shundo};}
