updateProgress=function(){updateProgressBeforeAvailability();if(!config().regional)return;const {total,shiny,shundo}=availabilityProgressStats();const percentage=count=>total?count/total*100:0;progressNum.innerHTML=shiny+'<span class="total">/ '+total+' shinies</span>';progressBar.style.width=percentage(shiny)+'%';progressWaitBar.style.width='0%';progressLabel.textContent=Math.round(percentage(shiny))+'% · Shinies (inclui shundos)';document.getElementById('shundoNum').innerHTML=shundo+'<span class="total">/ '+total+' shundos</span>';document.getElementById('shundoBar').style.width=percentage(shundo)+'%';document.getElementById('shundoLabel').textContent=Math.round(percentage(shundo))+'% · Shundos';};

