const tradePokemon=new Map();Object.entries(TABS).filter(([,c])=>c.regional).forEach(([id,c])=>c.list.flatMap(p=>p.forms||[p]).forEach(p=>tradePokemon.set(id+':'+p.slug,{...p,tabId:id,isForm:true})));
