function newTradeId(){return globalThis.crypto?.randomUUID?.()||'trade-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);}
function cleanTradeRecords(records){if(!Array.isArray(records))return [];const valid=new Map();for(const [index,record] of records.entries()){if(!record||!tradePokemon.has(record.key))continue;const clean={key:record.key,id:typeof record.id==='string'&&record.id?record.id.slice(0,200):'legacy-'+record.key+'-'+index};for(const field of ['person','date','offered','notes','offeredNotes','receiveNotes','offeredBackgroundName','receiveBackgroundName','offeredLuckyMethod','receiveLuckyMethod'])clean[field]=typeof record[field]==='string'?record[field].slice(0,4000):'';clean.offeredKey=tradePokemon.has(record.offeredKey)?record.offeredKey:'';for(const field of ['offeredVariant','receiveVariant'])clean[field]=['normal','shiny','shundo'].includes(record[field])?record[field]:'unknown';for(const field of ['offeredBackground','receiveBackground','offeredLucky','receiveLucky'])clean[field]=['yes','no'].includes(record[field])?record[field]:'unknown';for(const field of ['receiveBackgroundType','offeredBackgroundType'])clean[field]=['special','location'].includes(record[field])?record[field]:'unknown';for(const field of ['receiveVariant','offeredVariant'])if(clean[field]==='shundo')clean[field]='shiny';valid.set(clean.id,clean);}return [...valid.values()];}
try{tradeRecords=cleanTradeRecords(JSON.parse(localStorage.getItem(TRADE_STORAGE_KEY)));}catch{}
function persistTrades(){try{localStorage.setItem(TRADE_STORAGE_KEY,JSON.stringify(tradeRecords));}catch{showToast('Não foi possível salvar as trocas neste navegador.');}}
function importTradeRecords(records){tradeRecords=cleanTradeRecords(records);persistTrades();}
function tradeKey(p){return regionOwner.get(p.dex)+':'+p.slug;}
function saveTrade(p,fields){const key=tradeKey(p);if(!tradePokemon.has(key))return;const id=fields.id||newTradeId();const record=cleanTradeRecords([{...fields,key,id}])[0];const index=tradeRecords.findIndex(t=>t.id===id);if(index<0)tradeRecords.push(record);else tradeRecords[index]=record;persistTrades();return record;}
