const tradesScreen=document.createElement('section');tradesScreen.className='trades-screen';tradesScreen.hidden=true;tabs.before(tradesScreen);
function renderTrades(){tradesScreen.replaceChildren();const heading=document.createElement('h1');heading.textContent='↔ Trocas combinadas';const intro=document.createElement('p');intro.textContent='Seus Pokémon reservados para troca. As trocas pendentes não contam como coletadas.';tradesScreen.append(heading,intro);
 if(!tradeRecords.length){const empty=document.createElement('p');empty.className='home-empty';empty.textContent='Nenhuma troca combinada. Nas coleções regionais, dê três cliques em um Pokémon ou use o botão “Troca”.';tradesScreen.append(empty);return;}
 const list=document.createElement('div');list.className='trade-list';
 [...tradeRecords].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')).forEach(record=>{const p=tradePokemon.get(record.key);const card=document.createElement('article');card.className='trade-record';const image=document.createElement('img');image.src=p.shinyImage||'https://assets.dittobase.com/go/pokemon/'+p.dex+'-'+p.slug+'-shiny.png';image.alt=p.name;const title=document.createElement('h2');title.textContent='#'+p.dex+' '+p.name;card.append(image,title);
  const region=REGIONS.find(r=>'region-'+r[0]===p.tabId);const subtitle=document.createElement('p');subtitle.textContent=region[1]+' · Troca combinada';card.append(subtitle);
  for(const [label,value] of [['Pessoa',record.person||'Não informada'],['Data',record.date?record.date.split('-').reverse().join('/'):'A combinar'],['Vou trocar',record.offered||'Não informado'],['Observações',record.notes||'Sem observações']]){const field=document.createElement('p');const name=document.createElement('strong');name.textContent=label+': ';const text=document.createElement('span');text.textContent=value;field.append(name,text);card.append(field);}
  const actions=document.createElement('div');actions.className='trade-actions';
  const edit=document.createElement('button');edit.textContent='Editar';edit.onclick=()=>openTradeEditor(p);const remove=document.createElement('button');remove.textContent='Remover';remove.onclick=()=>{if(!confirm('Remover a troca combinada de '+p.name+'?'))return;tradeRecords=tradeRecords.filter(t=>t.key!==record.key);persistTrades();renderTrades();};actions.append(edit,remove);
  for(const [mark,label] of [[MARK_OWNED,'Recebido como shiny'],[MARK_WAITING,'Recebido como shundo']]){const receive=document.createElement('button');receive.textContent=label;receive.onclick=()=>{state[p.tabId].marks[p.slug]=mark;try{localStorage.setItem(TABS[p.tabId].storageKey,JSON.stringify(state[p.tabId].marks));}catch{showToast('Não foi possível salvar o progresso.');return;}tradeRecords=tradeRecords.filter(t=>t.key!==record.key);persistTrades();renderTrades();showToast('Pokémon recebido e marcado na coleção.');};actions.append(receive);}card.append(actions);list.append(card);
 });tradesScreen.append(list);
}
function showTrades(){currentTabId='trades';homeMode(false);document.querySelector('.wrap').classList.add('is-trades');tradesScreen.hidden=false;closeExportMenu();document.title='Trocas combinadas — Pokémon GO';renderTrades();}
const homeModeBeforeTrades=homeMode;homeMode=function(enabled){homeModeBeforeTrades(enabled);document.querySelector('.wrap').classList.remove('is-trades');tradesScreen.hidden=true;};
const renderHomeBeforeTrades=renderHome;renderHome=function(){renderHomeBeforeTrades();const button=document.createElement('button');button.className='home-collection home-trades';button.textContent='↔ Trocas combinadas ('+tradeRecords.length+') · Ver detalhes';button.onclick=showTrades;homeScreen.prepend(button);};
