function tradeDetailSection(prefix,title){return '<fieldset><legend>'+title+'</legend><label>Versão<select id="'+prefix+'Variant"><option value="unknown">Não informado</option><option value="normal">Normal</option><option value="shiny">Shiny</option></select></label><label>Sortudo<select id="'+prefix+'Lucky"><option value="unknown">Não informado</option><option value="yes">Sortudo combinado</option><option value="no">Sem garantia de sortudo</option></select></label><label>Como foi combinado? (opcional)<input id="'+prefix+'LuckyMethod" maxlength="500" placeholder="Globo, Pokémon antigo ou outros detalhes"></label><label>Possui fundo?<select id="'+prefix+'Background"><option value="unknown">Não informado</option><option value="no">Sem fundo</option><option value="yes">Com fundo</option></select></label><label>Tipo de fundo<select id="'+prefix+'BackgroundType"><option value="unknown">Não informado</option><option value="special">Fundo especial</option><option value="location">Fundo de localidade</option></select></label><label>Qual fundo? (opcional)<input id="'+prefix+'BackgroundName" maxlength="500" placeholder="Evento, local ou nome do fundo"></label><label>Detalhes desse Pokémon<textarea id="'+prefix+'Notes" rows="2" maxlength="4000" placeholder="PC, nível baixo, fantasia, golpe especial, etc."></textarea></label></fieldset>';}
