document.getElementById('tradeOffered').parentElement.after(tradeDetailFields);
function normalizedPokemonQuery(text){return String(text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/#/g,'').trim();}
function searchTradePokemon(query){const q=normalizedPokemonQuery(query);if(!q)return [];return [...tradePokemon.entries()].filter(([,p])=>normalizedPokemonQuery(p.name).includes(q)||String(p.dex)===q||p.slug.includes(q)).sort((a,b)=>a[1].dex-b[1].dex).slice(0,10);}
function tradeImageUrl(p,variant){if(!['shiny','shundo'].includes(variant)&&p.normalImage)return p.normalImage;const shiny=p.shinyImage||'https://assets.dittobase.com/go/pokemon/'+p.dex+'-'+p.slug+'-shiny.png';return !['shiny','shundo'].includes(variant)?shiny.replace('-shiny.png','.png'):shiny;}
function pokemonTradeVisual(p,variant){const block=document.createElement('div');block.className='trade-pokemon-visual';const image=document.createElement('img');image.src=tradeImageUrl(p,variant);image.alt=p.name;image.dataset.tradeImage='true';const name=document.createElement('strong');name.textContent='#'+p.dex+' '+p.name;block.append(image,name);const warning=tradeAvailabilityWarning(p);if(warning)block.append(warning);return block;}
function updateOfferedPreview(){const preview=document.getElementById('tradeOfferedPreview');preview.replaceChildren();const p=tradePokemon.get(selectedOfferedKey);if(p)preview.append(pokemonTradeVisual(p,document.getElementById('offeredVariant').value));}
document.getElementById('tradeOffered').addEventListener('input',()=>{selectedOfferedKey='';updateOfferedPreview();const suggestions=document.getElementById('tradeSuggestions');suggestions.replaceChildren();const query=document.getElementById('tradeOffered').value;const matches=searchTradePokemon(query);matches.forEach(([key,p])=>{const button=document.createElement('button');button.type='button';button.className='trade-suggestion';button.append(pokemonTradeVisual(p,'shiny'));button.onclick=()=>{selectedOfferedKey=key;document.getElementById('tradeOffered').value=p.name;suggestions.replaceChildren();updateOfferedPreview();};suggestions.append(button);});if(query.trim()&&!matches.length){const note=document.createElement('p');note.textContent='Nenhum Pokémon encontrado. Você pode manter o texto livre ou pesquisar por nome ou número.';suggestions.append(note);}});
