function findHomeSearchResults(query){const q=normalizedPokemonQuery(query);if(!q)return [];const number=/^\d+$/.test(q)?Number(q):null;return homeSearchIndex.filter(item=>number!==null?item.kind==='pokemon'&&item.p.dex===number:q.split(/\s+/).every(word=>item.terms.includes(word))).sort((a,b)=>{const score=item=>item.terms===q?0:item.kind==='collection'||item.kind==='trades'?1:item.terms.startsWith(q)?2:3;return score(a)-score(b)||(a.kind==='pokemon'&&b.kind==='pokemon'?Number(!TABS[a.tabId].regional)-Number(!TABS[b.tabId].regional)||a.p.dex-b.p.dex:0);}).slice(0,24);}
