 const block=document.createElement('section');block.className='home-search';block.setAttribute('aria-label','Pesquisa de coleções e Pokémon');const label=document.createElement('label');label.textContent='Aonde você quer ir?';const input=document.createElement('input');input.type='search';input.id='homeSearchInput';input.placeholder='Região, coleção, nome ou número da Pokédex…';input.autocomplete='off';label.setAttribute('for',input.id);const results=document.createElement('div');results.className='home-search-results';results.id='homeSearchResults';const hint=document.createElement('p');hint.className='home-search-hint';hint.textContent='Ex.: Kanto, Mega Dex, Pikachu, #025 ou Trocas combinadas';results.setAttribute('aria-live','polite');input.setAttribute('aria-controls',results.id);
 const inputWrap=document.createElement('div');inputWrap.className='home-search-input-wrap';const clear=document.createElement('button');clear.type='button';clear.className='home-search-clear';clear.textContent='×';clear.title='Limpar pesquisa';clear.setAttribute('aria-label','Limpar pesquisa');clear.hidden=true;clear.onclick=()=>{input.value='';matches=[];results.replaceChildren();clear.hidden=true;input.focus?.();};inputWrap.append(input,clear);let matches=[];input.addEventListener('input',()=>{clear.hidden=!input.value;results.replaceChildren();matches=findHomeSearchResults(input.value);if(!input.value.trim())return;if(!matches.length){const empty=document.createElement('p');empty.textContent='Nenhum resultado. Tente outro nome ou número da Pokédex.';results.append(empty);return;}for(const item of matches){const button=document.createElement('button');button.type='button';button.className='home-search-result';const title=document.createElement('strong');title.textContent=item.title;const detail=document.createElement('span');detail.textContent=item.detail+(archivedTabs.has(item.tabId)?' · Aba oculta':'');button.append(title,detail);button.onclick=()=>openHomeSearchResult(item);results.append(button);}});input.addEventListener('keydown',event=>{if(event.key==='Enter'&&matches.length){event.preventDefault();openHomeSearchResult(matches[0]);}});block.append(label,inputWrap,hint,results);return block;
