function tradeTodayKey(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const values=Object.fromEntries(parts.map(p=>[p.type,p.value]));return values.year+'-'+values.month+'-'+values.day;}
function validTradeDate(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return false;const date=new Date(value+'T12:00:00Z');return !Number.isNaN(date.getTime())&&date.toISOString().slice(0,10)===value;}
function nextTradeSummary(today=tradeTodayKey()){const dated=tradeRecords.filter(t=>validTradeDate(t.date));const upcoming=dated.filter(t=>t.date>=today).sort((a,b)=>a.date.localeCompare(b.date));const nextDate=upcoming[0]?.date||'';return {date:nextDate,records:upcoming.filter(t=>t.date===nextDate),overdue:dated.filter(t=>t.date<today).length,undated:tradeRecords.filter(t=>!validTradeDate(t.date)).length,today};}
function createNextTradeAlert(){const summary=nextTradeSummary();const box=document.createElement('section');box.className='next-trade-alert'+(summary.date===summary.today?' trade-today':'');box.setAttribute('aria-label','Próxima troca');const heading=document.createElement('strong');heading.textContent=summary.date?(summary.date===summary.today?'🔔 Troca marcada para hoje':'🔔 Próxima troca · '+summary.date.split('-').reverse().join('/')):'🔔 Próxima troca';box.append(heading);
 if(summary.records.length){const when=document.createElement('p');when.textContent=summary.records.length+' troca(s) em '+summary.date.split('-').reverse().join('/');box.append(when);for(const record of summary.records){const line=document.createElement('p');const p=tradePokemon.get(record.key);line.textContent=(record.person||'Pessoa não informada')+' · Vou receber '+(p?'#'+p.dex+' '+p.name:'Pokémon não informado');box.append(line);}const button=document.createElement('button');button.type='button';button.textContent='Ver trocas desta data';button.onclick=()=>{Object.assign(tradeView,{search:'',sort:'date',direction:'asc',variant:'all',dateStatus:'all',from:summary.date,to:summary.date});for(const [field,id] of [['search','tradeViewSearch'],['sort','tradeViewSort'],['direction','tradeViewDirection'],['variant','tradeViewVariant'],['dateStatus','tradeViewDateStatus'],['from','tradeViewFrom'],['to','tradeViewTo']])document.getElementById(id).value=tradeView[field];showTrades();};box.append(button);}else{const empty=document.createElement('p');empty.textContent='Nenhuma troca marcada para hoje ou para os próximos dias.';box.append(empty);}
 if(summary.overdue||summary.undated){const note=document.createElement('p');note.className='next-trade-note';note.textContent=[summary.overdue?summary.overdue+' troca(s) com data passada ainda pendente(s)':null,summary.undated?summary.undated+' troca(s) sem data definida':null].filter(Boolean).join(' · ');box.append(note);}return box;}
