function tradeDateOutline(date,today=tradeTodayKey()){if(!validTradeDate(date))return '';return date===today?'trade-date-today':date>today?'trade-date-future':'trade-date-past';}
const buildTradeCardBeforeDateOutline=buildTradeRecordCard;
buildTradeRecordCard=function(record,withActions=true){const card=buildTradeCardBeforeDateOutline(record,withActions);const dateClass=tradeDateOutline(record.date);if(withActions&&dateClass){card.classList.add(dateClass);card.dataset.tradeDateStatus=dateClass;card.title=record.date===tradeTodayKey()?'Troca marcada para hoje':record.date>tradeTodayKey()?'Troca marcada para uma data futura':'Data da troca já passou';}return card;};

