// Early tracking enabled by the user; this does not change the source release status.
const EARLY_TRACKABLE_MEGAS=new Set(['chandelure-mega']);
const releasedMegaRows=MEGA_CATALOG.filter(p=>p.isReleased||EARLY_TRACKABLE_MEGAS.has(p.slug));
const oldMegaEntries=new Map(TABS.mega.list.map(p=>[p.slug,p]));
function megaCatalogEntry(row){const old=oldMegaEntries.get(row.slug);return {...old,name:old?.name||row.name,dex:row.order,slug:row.slug,types:row.types.map(t=>t.name),category:old?.category||(row.PokemonSpecies?.isMythical?'mythical':row.PokemonSpecies?.isLegendary?'legendary':'normal'),released:row.isReleased||EARLY_TRACKABLE_MEGAS.has(row.slug),earlyTracking:EARLY_TRACKABLE_MEGAS.has(row.slug)&&!row.isReleased,normalImage:row.PokemonImage.find(i=>!i.isShiny)?.imageUrl,shinyReleased:row.isShinyReleased,shinyImage:row.PokemonImage.find(i=>i.isShiny)?.imageUrl};}
TABS.mega.list=releasedMegaRows.map(megaCatalogEntry).sort((a,b)=>a.dex-b.dex);TABS.mega.useShinyImages=true;
const UNRELEASED_MEGAS=MEGA_CATALOG.filter(p=>!p.isReleased&&!EARLY_TRACKABLE_MEGAS.has(p.slug)).map(megaCatalogEntry).sort((a,b)=>a.dex-b.dex);
const megaImagesBeforeCatalog=imageCandidates;imageCandidates=function(p){if(currentTabId!=='mega')return megaImagesBeforeCatalog(p);return [...new Set([p.shinyImage,'https://assets.dittobase.com/go/pokemon/'+p.dex+'-'+p.slug+'-shiny.png',p.normalImage].filter(Boolean))];};
const setMarkBeforeMegaCatalog=setMark;setMark=function(p,mark){if(currentTabId==='mega'&&UNRELEASED_MEGAS.some(row=>row.slug===p.slug))return;setMarkBeforeMegaCatalog(p,mark);};
const upcomingMegaSection=document.createElement('section');upcomingMegaSection.className='upcoming-mega-section';upcomingMegaSection.hidden=true;grid.after(upcomingMegaSection);
function renderUnreleasedMegas(){upcomingMegaSection.hidden=currentTabId!=='mega';if(currentTabId!=='mega')return;upcomingMegaSection.replaceChildren();const title=document.createElement('h2');title.textContent='Ainda não lançadas';const note=document.createElement('p');note.textContent='Somente exibição · Não contam no progresso · Atualizado em 12/10/2026';upcomingMegaSection.append(title,note);const cards=document.createElement('div');cards.className='upcoming-mega-grid';const saved=st().statusFilter;let visible;try{st().statusFilter='all';visible=UNRELEASED_MEGAS.filter(matchesFilters);}finally{st().statusFilter=saved;}const tatsugiri=visible.filter(p=>p.dex===978);for(const p of visible){if(p.dex===978){if(p!==tatsugiri[0])continue;cards.append(createMegaTatsugiriDeck(tatsugiri));}else cards.append(createUnreleasedMegaCard(p));}if(!visible.length){const empty=document.createElement('p');empty.textContent='Nenhuma Mega não lançada corresponde à busca e aos filtros.';cards.append(empty);}upcomingMegaSection.append(cards);}
const renderBeforeMegaCatalog=render;render=function(){renderBeforeMegaCatalog();renderUnreleasedMegas();};
const showHomeBeforeMegaCatalog=showHome;showHome=function(){upcomingMegaSection.hidden=true;showHomeBeforeMegaCatalog();};
const showTradesBeforeMegaCatalog=showTrades;showTrades=function(){upcomingMegaSection.hidden=true;showTradesBeforeMegaCatalog();};
function createUnreleasedMegaCard(p){const card=document.createElement('article');card.className='card unreleased-mega-card';card.setAttribute('aria-label',p.name+' · Ainda não lançada · Somente exibição');card.setAttribute('aria-disabled','true');const number=document.createElement('div');number.className='dex';number.textContent='#'+String(p.dex).padStart(3,'0');const img=document.createElement('img');img.alt=p.name+(p.shinyImage?' shiny':' · Imagem de referência');img.loading='lazy';const name=document.createElement('div');name.className='name';name.textContent=p.name;const tag=document.createElement('div');tag.className='category-badge';tag.textContent='⚠ Ainda não lançada';card.append(number,img,name,tag);if(!p.shinyImage&&!['floette-mega','zygarde-mega'].includes(p.slug)){const note=document.createElement('div');note.className='mega-image-note';note.textContent='Imagem shiny indisponível · referência normal';card.append(note);}attachImageFallback(img,p);return card;}
function createMegaTatsugiriDeck(forms){const key='mega:tatsugiri';const expanded=expandedEvolutionDecks.has(key);const deck=document.createElement('div');deck.className='evolution-deck mega-tatsugiri-deck';deck.classList.toggle('expanded',expanded);deck.dataset.megaDeck='tatsugiri';const primary=createUnreleasedMegaCard(forms[0]);primary.classList.add('mega-deck-top');primary.setAttribute('aria-disabled','false');primary.setAttribute('aria-label','Mega Tatsugiri · Segure para mostrar as formas · Sem marcação de coleção');const button=document.createElement('button');button.type='button';button.className='deck-toggle';button.textContent=expanded?'▤ Recolher formas':'▤ '+forms.length+' formas · segure';button.setAttribute('aria-expanded',String(expanded));function toggle(){if(currentTabId!=='mega')return;if(expandedEvolutionDecks.has(key))expandedEvolutionDecks.delete(key);else expandedEvolutionDecks.add(key);renderUnreleasedMegas();}button.onclick=toggle;primary.append(button);let timer;const cancel=()=>{clearTimeout(timer);};let origin;primary.addEventListener('pointerdown',event=>{if(event.button!==0||event.isPrimary===false||event.target.closest?.('.deck-toggle'))return;origin={x:event.clientX,y:event.clientY};timer=setTimeout(toggle,550);});primary.addEventListener('pointermove',event=>{if(origin&&Math.hypot(event.clientX-origin.x,event.clientY-origin.y)>10)cancel();});for(const type of ['pointerup','pointercancel','pointerleave'])primary.addEventListener(type,cancel);primary.addEventListener('contextmenu',event=>{event.preventDefault();cancel();});deck.append(primary);if(expanded)for(const form of forms.slice(1))deck.append(createUnreleasedMegaCard(form));return deck;}

